function(ctx){
  var out={schedule:false,visibility:false,original:false,errors:[]};
  var schedule=String(ctx.scheduleAt||'').trim();
  if(schedule){
    try{
      var d=new Date(schedule);
      if(isNaN(d.getTime()))throw new Error('bad date');
      var pad=function(n){return n<10?'0'+n:String(n);};
      var text=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes());
      var sw=document.querySelector('.post-time-wrapper .d-switch');
      if(sw){sw.click();}
      var input=document.querySelector('.date-picker-container input');
      if(!input){out.errors.push('未找到定时发布输入框');}
      else{
        input.focus();
        input.value=text;
        input.dispatchEvent(new Event('input',{bubbles:true}));
        input.dispatchEvent(new Event('change',{bubbles:true}));
        out.schedule=true;
        out.scheduleText=text;
      }
    }catch(e){out.errors.push('定时时间格式无效');}
  }
  var vis=String(ctx.visibility||'').trim();
  if(vis&&vis!=='公开可见'){
    var allowed={'仅自己可见':1,'仅互关好友可见':1};
    if(!allowed[vis]){out.errors.push('不支持的可见范围');}
    else{
      var dd=document.querySelector('div.permission-card-wrapper div.d-select-content');
      if(dd){dd.click();}
      var opts=document.querySelectorAll('div.d-options-wrapper div.d-grid-item div.custom-option');
      var hit=false;
      for(var i=0;i<opts.length;i++){
        if((opts[i].textContent||'').indexOf(vis)>=0){opts[i].click();hit=true;break;}
      }
      if(hit){out.visibility=true;out.visibilityValue=vis;}
      else{out.errors.push('未找到可见范围选项');}
    }
  }
  if(String(ctx.original||'').trim().toLowerCase()==='true'){
    var card=document.querySelector('div.custom-switch-card');
    var toggle=card?card.querySelector('div.d-switch'):document.querySelector('div.custom-switch-card div.d-switch');
    if(toggle){toggle.click();out.original=true;}
    else{out.errors.push('未找到原创声明开关');}
  }
  return out;
}

function(){
  var buttons=document.querySelectorAll('button.custom-button');
  for(var i=0;i<buttons.length;i++){
    if((buttons[i].textContent||'').trim()==='暂存离开'){buttons[i].click();return {saved:true};}
  }
  return {saved:false,error:'未找到暂存离开按钮'};
}
